    Lines with the same footprint share rows (a stacked pair and a floor-only
    pallet of the same build fit side by side), so their floor positions are
    summed before rounding up to rows. Different footprints never share rows.
    """
    positions_by_footprint: dict[tuple[int, int], int] = {}
