        positions_by_footprint[line.footprint] = (
            positions_by_footprint.get(line.footprint, 0) + _floor_positions(line)
        )
    total = 0
    for (length_in, width_in), positions in positions_by_footprint.items():
        rows = math.ceil(positions / _per_row(width_in))
        total += rows * length_in
    return total

